                        影箭_info: '准备阶段开始时,你可以弃一张牌并视为使用一张无距离限制的【杀】.',
                        请戍: '请戍',
                        请戍_info: '蜀势力技,当一名角色成为【杀】的目标后,你可以弃一张牌,视为对此【杀】使用者使用了一张【杀】.',
                        熾魂: '熾魂',
                        熾魂_info: '魏势力技,出牌阶段限一次,你可以弃一张牌,令一名已受伤的角色回复一点体力.若你弃置的牌为【桃】或【酒】,你令一名角色翻面.你对武将牌背面朝上的角色使用牌无次数和距离限制',
                        五岳: '五岳',
                        五岳_info: '当你进入濒死时,你可以亮出牌堆顶5张牌,弃置其中的红色牌并回复等量体力,获得其余牌.',
                        游侠: '游侠',
                        游侠_info: '出牌阶段开始时,你可以用一张牌依次与所有体力值与你相同的其他角色拼点,赢的角色摸一张牌,没赢的角色受到你造成的一点伤害.',
                        残戾: '残戾',
                        残戾_info: '锁定技,结束阶段,你选择一项:1.弃置三张不同类型的手牌,可以视为使用一张基本牌;2.减一点体力上限,摸三张牌.',
                        父魂: '父集智魂',
                        父魂_info: '你可以将两张手牌当做【杀】使用或打出,若这两张牌花色相同,你摸一张牌;出牌阶段,若你以此法使用的【杀】造成了伤害,你获得技能〖武圣〗和〖咆哮〗直到回合结束.',
                        fu222: '父魂',
