                        射戟_info: '锁定技,当你使用【杀】对目标角色造成伤害时,若你不在其攻击范围内,则此杀伤害+1;当你装备着武器时,你使用红色【杀】无距离限制.',
                        犬计: '犬计',
                        犬计_info: '出牌阶段,你可以选择至多三张手牌,若你选择的牌的数量为:1,你将此牌当作随机一张普通锦囊牌使用,当你为此牌指定目标后,目标改为随机一名角色;2,你将这些牌当作随机一张普通锦囊牌使用;3,你将这些牌当作你指定的一张普通锦囊牌使用.',
                        佢守: '佢守',
                        佢守_info: '锁定技,当你受到伤害时,你进行判定,若为红色,此伤害-1,若为黑色,此伤害+1.',
                        征兆: '征兆',
                        征兆_info: '你距离1以内的角色出牌阶段开始时,你可以预测其此阶段使用的牌数(至少为1,至多为5).此阶段结束时,若你预测成功,你摸等量的牌.',
                        貔魔: '貔魔',
                        貔魔_info: '锁定技,当你摸牌时,若你的体力不为全场最多,你令体力值为全场最多的一名角色摸等量的牌.',
                        暗恋: '暗恋',
                        暗恋_info: '回合结束时,你可以将一张牌置于一名男性角色武将牌上,称为<恋>,其出牌阶段开始时,选择一项:1.将<恋>置入弃牌堆,弃置与<恋>花色相同的牌;2.获得<恋>,你摸X张牌(X为其与<恋>同花色的牌数).',
                        呤作: '呤作',
                        呤作_info: '出牌阶段限一次,你可以展示一名其他角色的所有手牌并选择其中一张基本牌或锦囊牌,直到你下个回合开始,你可以将一张牌当作此牌使用或打出(每回合限一次).',
                        暗恋2: '暗恋2',
                        暗恋2_info: '',
                        问道: '问道',
                        问道_info: '出牌阶段限一次,你可以将至多四张与你武将牌上的牌花色均不相同的牌置于武将牌上,摸等量的牌.当一张判定牌生效前,你可以用武将牌上的一张牌代替判定牌,立即生效.',
                        驱恶: '驱恶',
                        驱恶_info: '准备阶段,你可以选择一项:1.令一名角色回复你上个回合开始时武将牌的状态;2.令一名角色弃置判定区的所有牌.',
                        狩境: '狩境',
