                        战姬: '战姬',
                        战姬_info: '锁定技,当你使用【杀】指定目标后,其只能用与此【杀】同花色的【闪】响应;当你使用【决斗】指定一个目标或成为一名角色【决斗】的目标后,其只能用与此【决斗】同花色的牌响应.',
                        武勇: '武勇',
                        武勇_info: '准备阶段,你可以视为对一名其他角色使用一张无距离限制的【杀】,若此【杀】造成了伤害,你本回合出牌阶段使用【杀】的次数改为你当前体力值.',
                        止戈: '止戈',
                        止戈_info: '出牌阶段限一次,你可以令一名攻击范围内含有你的其他角色交给你一张【杀】或武器牌,否则其视为对你指定的另一名其攻击范围内的角色使用了一张由你指定属性的【杀】.',
                        df_宗祚: '宗祚',
                        df_宗祚_info: '锁定技,游戏的第一个回合开始前,你加X点体力上限并回复X点体力并摸X张牌(X为全场势力数),立即进入你的回合;当一名角色死亡后,若没有与其势力相同的角色,你减1点体力上限并摸两张牌.',
                        忠勇: '忠勇',
                        忠勇_info: '当一名角色使用【杀】指定目标后,你可以弃一张牌令此【杀】伤害+1,若如此做,此【杀】结算完毕后,你与使用者各摸一张牌,若此【杀】为红色,使用者回收此牌.',
                        护彝: '护彝',
