                        血佑: '血佑',
                        血佑_info: '一名角色的出牌阶段开始时,你可以减一点体力上限,令攻击范围内的一名体力值大于其的其他角色选择一项:令当前回合角色获得<无双>;弃置两张手牌.此阶段结束时,若此阶段进入弃牌堆的牌数大于进行选择的体力值,你增加一点体力上限并回复一点体力.',
