                                event = event || _status.event;
                                var filter = event._backup.filterCard;
                                var color = get.color(card, player);
                                var color1 = player.storage.双雄 == 'red' ? 'black' : 'red';
                                var color2 = player.storage.双雄 == 'red' ? 'red' : 'black';
                                if (color == color1 && filter({ name: 'juedou', cards: [card] }, player, event)) return true;
                                if (color == color2 && filter({ name: 'sha', cards: [card] }, player, event)) return true;
                                return false;
